    tree = defaultdict(list)
    for i in range(2, n + 1):
        tree[superiors[i - 2]].append(i)

    # Function to perform DFS and get the command spreading sequence
    def get_spreading_sequence(start):
        sequence = []
        stack = [start]
        while stack:
            node = stack.pop()
            sequence.append(node)
